#include "ndpi_api.h"
#include "ndpi_private.h"
#include "ndpi_classify.h"
#include "fuzz_common_code.h"

#include <stdint.h>
#include <stdio.h>
#include <assert.h>
#include "fuzzer/FuzzedDataProvider.h"

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  FuzzedDataProvider fuzzed_data(data, size);
  struct ndpi_detection_module_struct *ndpi_info_mod;
  struct ndpi_flow_struct flow;
  u_int8_t protocol_was_guessed, unused;
  u_int32_t i, ret;
  u_int16_t bool_value;
  struct ndpi_bitmask enabled_bitmask;
  struct ndpi_lru_cache_stats lru_stats;
  struct ndpi_patricia_tree_stats patricia_stats;
  struct ndpi_automa_stats automa_stats;
  int cat, idx;
  u_int16_t pid, pid2;
  char *protoname, *protoname2;
  char pids_name[32];
  const char *name;
  char catname[] = "name";
  struct ndpi_flow_input_info input_info;
  ndpi_proto p, p2;
  char out[128];
  struct ndpi_global_context *g_ctx;
  char log_ts[32];
  int value;
  char cfg_value[32];
  char cfg_proto[32];
  char cfg_param[32];
  u_int64_t cat_userdata = 0;
  u_int16_t unused1, unused2;
  ndpi_master_app_protocol proto1, proto2;

  /* Make allocation failures more unlikely */
  if(fuzzed_data.ConsumeBool())
    fuzz_set_alloc_callbacks_and_seed(size);
  else
    fuzz_set_alloc_callbacks_and_seed(0);

  if(fuzzed_data.ConsumeBool())
    g_ctx = ndpi_global_init();
  else
    g_ctx = NULL;

  if(ndpi_bitmask_alloc(&enabled_bitmask, ndpi_get_num_internal_protocols()) == 0) {
    ndpi_bitmask_set_all(&enabled_bitmask);
    if(fuzzed_data.ConsumeBool()) {
      ndpi_bitmask_reset(&enabled_bitmask);
      for(i = 0; i < ndpi_get_num_internal_protocols(); i++) {
        if(fuzzed_data.ConsumeBool())
          ndpi_bitmask_set(&enabled_bitmask, i);
      }
    }
